import{_ as o,o as t,c as d,af as a}from"./chunks/framework._zKnALF5.js";const g=JSON.parse('{"title":"JWT 与房间鉴权（服务端详解）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/jwt-room-auth.md","filePath":"guide/jwt-room-auth.md","lastUpdated":null}'),r={name:"guide/jwt-room-auth.md"};function c(s,e,i,n,l,h){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="jwt-与房间鉴权-服务端详解" tabindex="-1">JWT 与房间鉴权（服务端详解） <a class="header-anchor" href="#jwt-与房间鉴权-服务端详解" aria-label="Permalink to &quot;JWT 与房间鉴权（服务端详解）&quot;">​</a></h1><p><code>xymj-colyseus-server</code> 将 <strong>HTTP 签发的 JWT</strong> 与 <strong>Colyseus 进房</strong> 打通：服务端通过 <code>@RequireAuth()</code>、<code>JWTUtil</code> 与 Redis 会话存储完成校验。与 Colyseus 官方概念对照：<a href="https://docs.colyseus.io/authentication/" target="_blank" rel="noreferrer">Authentication</a>、<a href="https://docs.colyseus.io/authentication/room" target="_blank" rel="noreferrer">Room Authentication</a>。</p><h2 id="_1-两条通道-http-api-vs-websocket-房间" tabindex="-1">1. 两条通道：HTTP API vs WebSocket 房间 <a class="header-anchor" href="#_1-两条通道-http-api-vs-websocket-房间" aria-label="Permalink to &quot;1. 两条通道：HTTP API vs WebSocket 房间&quot;">​</a></h2><table tabindex="0"><thead><tr><th>通道</th><th>典型用法</th><th>服务端校验</th></tr></thead><tbody><tr><td>HTTP</td><td><code>Authorization: Bearer &lt;accessToken&gt;</code></td><td><code>authMiddleware</code>：校验 JWT 签名，写入 <code>req.user</code></td></tr><tr><td>Colyseus 房间</td><td><code>joinOrCreate</code> / <code>joinById</code> 的 <strong>options</strong></td><td><code>@RequireAuth()</code>：校验 JWT + <strong>Redis 会话</strong></td></tr></tbody></table><p>HTTP 与房间 <strong>共用同一套访问令牌</strong>（access token 字符串），但房间侧额外依赖 Redis（见下文）。</p><h2 id="_2-访问令牌从哪里来" tabindex="-1">2. 访问令牌从哪里来 <a class="header-anchor" href="#_2-访问令牌从哪里来" aria-label="Permalink to &quot;2. 访问令牌从哪里来&quot;">​</a></h2><p>以下路径都会在成功后签发 <strong>访问令牌</strong>（响应里的 <code>token</code> 或业务返回体中的 <code>tokens.accessToken</code>，以接口为准），并把令牌写入 Redis：</p><ul><li><code>POST /api/auth/register</code>、<code>POST /api/auth/login</code>：<code>AuthService</code> 写入 <code>access_token:${userId}</code>、<code>refresh_token:${userId}</code>。</li><li><code>GET /api/minigame/weixin/login</code>、<code>GET /api/minigame/douyin/login</code>：<code>AccessTokenAndLoginService</code> 在创建/查找本地用户后同样写入上述 Redis 键。</li></ul><p>JWT 由 <code>jsonwebtoken</code> 使用配置项 <code>JWT_SECRET</code>（及过期时间 <code>JWT_EXPIRES_IN</code> 等，见 <a href="/guide/configuration.html">配置说明</a>）签名；payload 至少包含 <code>userId</code>，并可含 <code>username</code>、<code>email</code>、<code>openid</code>、<code>platform</code> 等扩展字段（小游戏登录会带平台相关声明）。</p><h2 id="_3-加入房间时必须带什么" tabindex="-1">3. 加入房间时必须带什么 <a class="header-anchor" href="#_3-加入房间时必须带什么" aria-label="Permalink to &quot;3. 加入房间时必须带什么&quot;">​</a></h2><p>对被 <code>@RequireAuth()</code> 保护的 <code>onCreate</code> / <code>onJoin</code>，客户端应在 options 中传入：</p><p><strong>（客户端代码）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>token: &quot;&lt;accessToken&gt;&quot;</span></span></code></pre></div><p>或使用同义字段 <strong><code>accessToken</code></strong>（二者等价，实现见服务端 <code>RequireAuth</code>）。</p><p>缺省时服务端抛出「未提供认证令牌」，连接将被拒绝。</p><h2 id="_4-requireauth-校验顺序-核心逻辑" tabindex="-1">4. <code>@RequireAuth()</code> 校验顺序（核心逻辑） <a class="header-anchor" href="#_4-requireauth-校验顺序-核心逻辑" aria-label="Permalink to &quot;4. `@RequireAuth()` 校验顺序（核心逻辑）&quot;">​</a></h2><p>装饰器写在 <strong><code>Room</code></strong> 的 <code>onJoin</code> / <code>onCreate</code> 等方法上的写法与注意事项（示例代码）见 <a href="/rooms/auth.html#room-auth-decorators">鉴权与权限 · 注解（装饰器）</a>。</p><p>实现位于服务端 <code>src/utils/decorators/RequireAuth.ts</code>，流程概括为：</p><ol><li><strong><code>NODE_ENV === &#39;test&#39;</code></strong>：直接放行（便于单测不依赖 Redis）。</li><li>从 <strong>房间 options</strong> 读取 <code>token</code> 或 <code>accessToken</code>。</li><li><strong><code>JWTUtil.verifyAccessToken</code></strong>：验证签名与有效期；失败则拒绝。</li><li><strong>Redis</strong>： <ul><li>若存在键 <strong><code>access_token:${userId}</code></strong>：必须与本次传入的 token <strong>字符串完全一致</strong>，否则「令牌不匹配」。</li><li>若 <strong>没有</strong> <code>access_token</code>：则要求存在 <strong><code>refresh_token:${userId}</code></strong>，否则视为「令牌已过期或无效」。</li></ul></li></ol><p>通过后，会把 <strong><code>userId</code>、<code>username</code>、<code>email</code></strong> 以及完整 <strong><code>tokenPayload</code></strong> 写回 <strong>options</strong>，房间逻辑里可直接使用（例如聊天频道里的 <code>guildId</code> / <code>teamId</code> 仍由客户端 options 传入，见 <a href="/reference/protocol.html">消息协议</a>）。</p><h3 id="设计含义-接入时要注意" tabindex="-1">设计含义（接入时要注意） <a class="header-anchor" href="#设计含义-接入时要注意" aria-label="Permalink to &quot;设计含义（接入时要注意）&quot;">​</a></h3><ul><li><strong>仅 JWT 合法还不够</strong>：默认还要求 Redis 里仍有登录会话；单机调试若清空 Redis，会出现 JWT 未过期但进房失败。</li><li><strong>多端登录 / 顶号</strong>：新登录会覆盖 Redis 中的 <code>access_token</code>；旧客户端仍持旧 token 时，会因「令牌不匹配」被拒绝进房（有利于会话一致性，可按产品需求再扩展）。</li><li><strong><code>userId</code> 语义</strong>：账号密码与小游戏统一为库表用户主键（UUID 字符串）；小游戏登录不再用 openid 作为 JWT 的 <code>userId</code>。</li></ul><h2 id="_5-http-接口侧的-jwt" tabindex="-1">5. HTTP 接口侧的 JWT <a class="header-anchor" href="#_5-http-接口侧的-jwt" aria-label="Permalink to &quot;5. HTTP 接口侧的 JWT&quot;">​</a></h2><p><code>authMiddleware</code>（<code>src/middleware/auth.middleware.ts</code>）从 <strong><code>Authorization: Bearer &lt;token&gt;</code></strong> 解析令牌，校验签名后挂载到 <code>req.user</code>。与房间的 Redis 二次校验 <strong>独立</strong>：某些 HTTP 路由若只用该中间件，行为与 <code>@RequireAuth()</code> 不完全相同，以具体控制器是否叠加校验为准。</p><h2 id="_6-与各引擎客户端的衔接" tabindex="-1">6. 与各引擎客户端的衔接 <a class="header-anchor" href="#_6-与各引擎客户端的衔接" aria-label="Permalink to &quot;6. 与各引擎客户端的衔接&quot;">​</a></h2><p>客户端需在 <strong>建立 Colyseus 连接之后、加入房间时</strong> 把 HTTP 拿到的 access token 放进 join options（具体 API 见各引擎官方文档）：</p><ul><li>Unity：<code>JoinOrCreate&lt;MyState&gt;(&quot;room_name&quot;, new Dictionary&lt;string, object&gt; { [&quot;token&quot;] = accessToken })</code>（字段名与官方示例一致即可）。</li><li>Cocos / JS：<code>client.joinOrCreate(&quot;room_name&quot;, { token: accessToken })</code>。</li><li>Godot：join 参数字典中传入 <code>token</code> 或 <code>accessToken</code>（与 Colyseus Godot 文档中的 options 一致）。</li></ul><p>更完整的引擎安装与官方教程索引见：</p><ul><li><a href="/engine/unity.html">Unity</a></li><li><a href="/engine/cocos-creator.html">Cocos Creator</a></li><li><a href="/engine/godot.html">Godot</a></li></ul><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to &quot;7. 常见问题&quot;">​</a></h2><ul><li><strong>JWT 刚刷新但进房仍失败</strong>：确认服务端是否同步更新了 Redis 的 <code>access_token:${userId}</code>；仅本地换新 JWT 而不同步 Redis，会与 <code>@RequireAuth</code> 不一致。</li><li><strong>Redis 挂了或未连接</strong>：<code>RequireAuth</code> 中取 Redis 可能失败，表现为授权失败；生产环境应保证 Redis 可用或与代码策略一致。</li><li><strong>压测房</strong>：<code>loadtest_room</code> 等为无鉴权场景专用，不参与 JWT 进房流程；勿与业务房间混淆。</li></ul><h2 id="_8-延伸阅读" tabindex="-1">8. 延伸阅读 <a class="header-anchor" href="#_8-延伸阅读" aria-label="Permalink to &quot;8. 延伸阅读&quot;">​</a></h2><ul><li>房间内参数约定：<a href="/rooms/auth.html">鉴权与权限</a></li><li>HTTP API 与登录：<a href="/reference/api.html">API 概览</a>、<a href="/reference/minigame/weixin.html">微信小游戏登录</a>、<a href="/reference/minigame/douyin.html">抖音小游戏登录</a></li></ul>',33)])])}const p=o(r,[["render",c]]);export{g as __pageData,p as default};
